Consider $\psi(z)= arctan(z/2)$. Then
\begin{equation}
\psi(z)=\sum_{i=1}\frac{(-1)^{i-1}2^{1-2i}}{2i-1}z^{2i-1}
\end{equation}
In this case, $$\mathscr{C}(\psi,1)=1+\sum_{i=1}^\infty i\cdot |c_{i}|\leq 1+\sum_{i=1}^\infty 2^{1-2i}\leq \mathcal{O}(1).$$

We say a function $\phi(\cdot,\cdot):\mathbb{R}^d\times \mathbb{R}^d\to \mathbb{R}$ is positive definite if for all $n \in \mathbb{N}$, any $\{x_1,...,x_n\}\subseteq \mathbb{R}^d, \{c_1,...,c_n\}\subseteq \mathbb{R}$,
\begin{equation}
\sum_{i,j}c_ic_j\phi(x_i,x_j)\geq 0.
\end{equation}

\label{a1}
\caption{Training RNN with SGD}
{\bf Input:} Data set ${\cal D}$, learning rate $\eta$.\\
The entries of $\bm{W}^0,\bm{A}$ are i.i.d. generated from $N(0,\frac{2}{m})$. The entries of $\bm{B}$ are i.i.d. generated from $N(0,\frac{1}{m})$.\\
\For {$t=1,2,3...n$}{
Randomly sample $(x_t, y_t)$ from the data set ${\cal D}$.\\
$\bm{W}^t=\bm{W}^{t-1}-\eta\nabla_{\bm{W}^{t-1}}\ell(y_t\cdot f(\bm{W}^{t-1},x_t))$.
}

\label{tt}
Assume there is $\delta\in (0,e^{-1}]$.  Supposing for ${\cal D}=\{x_i,y_i\}$, there is a function $F^*$ belonging to the concept class (\ref{cop}) or (\ref{cop2}) such that $y_i\cdot F^*(x_i)\geq 1$ for all $i$.  Let $\bm{W}^k$ be the output of Algorithm \ref{a1}. There is a parameter $m^*(n,\delta,L,\mathscr{C}^*)=poly(n,\delta^{-1},L,\mathscr{C}^*)$  such that, with probability at least $1-\delta$, if $m>m^*(n,\delta,L)$, there exits parameter $\eta= \mathcal{O}(1/ m)$ that satisfies
\begin{equation}
\frac{1}{n}\sum_{k=1}^nL^{0-1}_{{\cal D}}(\bm{W}^k)\leq \widetilde{\mathcal{O}}[\frac{(\mathscr{C}^*)^2}{n}]+\mathcal{O}(\frac{\log(1/\delta)}{n}).
\end{equation}

\label{mt}
Under the condition of Theorem \ref{tt}, let $n$ samples in the training set be $\{x_i,y_i\}_{i=1}^n$. $\widetilde{y}=[F^*(x_1),F^*(x_2),...F^*(x_n)]^T$. Let $\bm{H}$ be a matrix with $H_{i,j}= \frac{1}{m}\langle \nabla_{\widetilde{W}} f(\widetilde{\bm{W}},x_i),\nabla_{\widetilde{W}} f(\widetilde{\bm{W}},x_j) \rangle$. The entries of $\widetilde{\bm{W}}$ are i.i.d. generated from $N(0,\frac{2}{m})$.
If there is a matrix $\bm{H}^\infty \in \mathbb{R}^{n\times n}$ satisfying
\begin{equation}\label{condition1}
\bm{H} +\bm{\epsilon}^T\bm{\epsilon} \succeq \bm{H}^\infty \text{ with } ||\bm{\epsilon}||_F\leq 0.01/\mathcal{O}(\mathscr{C}^*),
\end{equation}
and $\sqrt{\widetilde{y}^T (\bm{H}^\infty)^{-1}\widetilde{y}}\leq \mathcal{O}(\mathscr{C}^*)$,
there exits $m^*(n,\delta^{-1},L,\mathscr{C}^*)=poly(n,\delta^{-1},L,\mathscr{C}^*)$ such that, with probability at least $1-\delta$, if $m>m^*$,
\begin{equation}
\frac{1}{n} \sum_{k=1}^n L^{0-1}_{{\cal D}}(\bm{W}^k)\leq \widetilde{\mathcal{O}}[\frac{\widetilde{y}^T (\bm{H}^\infty)^{-1}\widetilde{y}}{n}]+\mathcal{O}(\frac{\log(1/\delta)}{n}).
\end{equation}

\label{mc}
Under the condition of Theorem \ref{mt}, with probability at least $1-\delta$, there exits matrix $\bm{H}^\infty$ satisfying (\ref{condition1}) and
\begin{equation}\label{ec}
\sqrt{\widetilde{y}^T (\bm{H}^\infty)^{-1}\widetilde{y}}\leq \mathcal{O}(\mathscr{C}^*).
\end{equation}

\label{tt5}
For fixed $i,j$, under the condition in Theorem \ref{mt}, with probability at least $1-exp(-\Omega(\log^2m))$,
\begin{equation}
|\langle h_l(x_i),h_l(x_j) \rangle -K^l_{i,j}|\leq \mathcal{O}(l^{16}\cdot\log^2 m/\sqrt{m})
\end{equation}
And let $Q_l=\sqrt{(1+\frac{1}{L^3}\sum_{k=1}^l||X_{i,k}||^2)\cdot(1+\frac{1}{L^3}\sum_{k=1}^l||X_{j,k}||^2) }$,
\begin{equation}\label{ek}
\begin{aligned}
&K^1_{i,j}= Q_1\cdot \sum_{r=0}^\infty \mu^2_r [(1+\frac{1}{L^3}X_{i,1}^TX_{j,1})/Q_1]^r\\
&K^{l}_{i,j}=Q_l\cdot \sum_{r=0}^\infty \mu^2_r (\{\frac{1}{L^3}X_{i,l}^TX_{j,l}+ K^{l-1}_{i,j}\}/Q_l)^r
\end{aligned}
\end{equation}
In the above equations, $\mu_r=\frac{1}{\sqrt{2\pi}}\int_0^\infty \sqrt{2}xh_r(x)e^{-\frac{x^2}{2}}dx$, $h_r(x)=\frac{1}{\sqrt{r!}}(-1)^re^{\frac{x^2}{2}}\frac{d^r}{dx^r}e^{-\frac{x^2}{2}}.$

