A random variable $X$ is said to be sub-Gaussian with variance proxy $\sigma^2$ if $ \mathbb{E}[X]=0$ and for all $s\in\mathbb{R}$,
\begin{equation}
\mathbb{E}[e^{sX}]\leq e^{\frac{\sigma^2s^2}{\sigma^2}}.
\end{equation}
A random variable X is said to be $\lambda$-sub-exponential if $ \mathbb{E}[X]=0$, and for all $s$ that $|s|\leq \frac{1}{\lambda}$,
\begin{equation}
\mathbb{E}[e^{sX}]\leq e^{\frac{s^2\lambda^2}{2}}
\end{equation}

\label{ci}
Let $X_1,X_2,...X_m$ be i.i.d $\lambda$-sub-exponential  random variable with $\lambda<\mathcal{O}(1)$. Let $0<\epsilon\leq 1$. With probability at least $1-exp[\Omega(m\epsilon^2)]$,
\begin{equation}
|\frac{1}{m}\sum_{i=1}^mX_i|\leq \epsilon
\end{equation}

\label{nei}
Consider $M\in \mathbb{R}^d$, all  the entries of $M$ are i.i.d. generated from $N(0,\frac{1}{d})$, and $X_1,X_2\in\mathbb{R}^d$ with $||X_1||=||X_2||=1$. Let $\mu_i(\phi)$ denote the $i-$th Hermite coefficient of function $\phi$, i.e.
$\mu_r(\phi)=\frac{1}{\sqrt{2\pi}}\int_0^\infty \phi(x)h_r(x)e^{-\frac{x^2}{2}}dx$, $h_r(x)=\frac{1}{\sqrt{r!}}(-1)^re^{\frac{x^2}{2}}\frac{d^r}{dx^r}e^{-\frac{x^2}{2}}.$

We have
\begin{equation}
\underset{M}{\mathbb{E}} \phi_1(M^TX_2)\phi_2(M^TX_1)=\sum_r \mu_r(\phi_1)\mu_r(\phi_2)(X_1^TX_2)^{r}.
\end{equation}

\begin{equation}
\underset{M}{\mathbb{E}} \phi(M^TX_2)\phi(M^TX_1)=\sum_r \mu^2_r(\phi)(X_1^TX_2)^{r}.
\end{equation}

\label{fj}
Let $\bm{W}\in \mathbb{R}^{m\times d}$. All  the entries of $M$ are i.i.d. generated from $N(0,\frac{2}{m})$, and $X_1,X_2\in\mathbb{R}^d$ with $||X_1||=||X_2||=1$. $\phi(x)=\max(0,x)$ denotes the ReLU activation function. $\mu_i(\phi)$ denotes the $i-$th Hermite coefficient of function $\phi$. $W_i$ denotes the $i$-th row of $\bm{W}$.
With probability at least $1-exp(-\Omega(\log^2m ))$,
\begin{equation}
\begin{aligned}
\phi^T(\bm{W}X_1)\phi(\bm{W}X_2)&=\sum_i \phi^T(W_iX_1)\phi(W_iX_2)\\
&=\mathbb{E}_{w\sim N(0, I_d)}\phi(w^TX_1)\phi(w^TX_2)\pm \mathcal{O}(\frac{\log m}{\sqrt{m}})\\
&=\sum_r \mu_r(\phi)\mu_r(\phi)(X_1^TX_2)^{r} \pm \mathcal{O}(\frac{\log m}{\sqrt{m}}).
\end{aligned}
\end{equation}

\label{fj2}
Consider functions $\phi_1(x)=\sqrt{2}\max(0,x)$ and $\phi_2(x)=\sqrt{2}\mathbbm{1}\{x>0\}$. Let $X_1, X_2\in \mathbb{R}^d, ||X_1||= ||X_2||=1$, $z=X_1^TX_2$.
\begin{equation}
\mathbb{E}_{w\sim N(0, I_d)}\phi_1(w^TX_1)\phi_1(w^TX_2)=\frac{\sqrt{1-z^2}+(\pi-arccos(z))z}{\pi},
\end{equation}
and
\begin{equation}
\mathbb{E}_{w\sim N(0, I_d)}\phi_2(w^TX_1)\phi_2(w^TX_2)=\frac{\pi-arccos(z)}{\pi}.
\end{equation}

\label{bt}
For fixed vector $x\in \mathbb{R}^d$, $y, z\in \mathbb{R}^m$. With probability at least $1-exp(-\Omega(m/L^2))$
\begin{equation}
||\mathbbm{1}_{\bm{W}_0y+\bm{A}x>0} \cdot \bm{W}_0z||_2\leq ||z||_2(1+1/100L).
\end{equation}
For fixed $x\in \mathbb{R}^d$ and all $y,z$:
\begin{equation}
||\mathbbm{1}_{\bm{W}_0y+\bm{A}x>0} \cdot \bm{W}_0z||_2\leq ||z||_2(1+1/50L).
\end{equation}

\label{lf}
With probability at least $1-\mathcal{O}(n)\cdot exp(-\Omega(\log m))$, for all $i\in [n]$ and $\bm{W},\bm{W}'\in B(\bm{W}_0,\omega)$,
\begin{equation}
|f(\bm{W}',x_i)-f(\bm{W},x_i)-\langle \nabla f(\bm{W},x_i), \bm{W}'-\bm{W}\rangle |\leq \mathcal{O}(\omega^{1/3}L^{10}\log m \sqrt{m})||\bm{W}'-\bm{W}||_2.
\end{equation}

Let
\begin{equation}
\begin{aligned}
&h_L(x)=h_L(\bm{W},x),\  h_L(\bm{W'},x)=h_L(x)+h'_L(x),\\
&D_l=D_l(\bm{W},x),\ D_l'=D_l(\bm{W}',x), \ D^0_l=D_l(\bm{W}_0,x).
\end{aligned}
\end{equation}
By Claim G.2 in \cite{rate}, there exits diagonal matrices $D''_l$, $\{D''_l\}_{ii}\neq 0$ if and only if $ \{D'_l\}_{ii}\neq 0$, $||D''_l||_0\leq ||D_l'||_0\leq \mathcal{O}(L^{10/3}\tau_0^{2/3}m^{2/3})$, and
\begin{equation}
\begin{aligned}
B^T(h_L(x)+h'_L(x))-B^Th_L(x)=&\sum_{l=1}^{L-1}B^T(D_L+D''_L)\bm{W}'...(D_{l+1}+D''_{l+1})\\
&\cdot (\bm{W}'-\bm{W})h_l(x).
\end{aligned}
\end{equation}

Then,
\begin{equation}
\begin{aligned}
&f(\bm{W}',x_i)-f(\bm{W},x_i)-\langle \nabla f(\bm{W},x_i), \bm{W}'-\bm{W}\rangle\\
&=\sum_{l=1}^{L-1}B^T(D_L+D''_L)\bm{W}'...(D_{l+1}+D''_{l+1})\cdot (\bm{W}'-\bm{W})h_l(x)\\
&-B^TD_L\bm{W}...\bm{W}D_{l+1}\cdot (\bm{W}'-\bm{W})h_l(x).
\end{aligned}
\end{equation}
To prove the theorem, same as Lemma 5.7 in \cite{allenzhu2019convergence}, we have the following result:
Let $D^{0/1}_l$  be diagonal matrix and $(D^{0/1}_l)_{ii}=0$ if $(D_l+D''_l-D^0_l)_{ii}=0$,  $(D^{0/1}_l)_{ii}=1$ if $(D_l+D''_l-D^0_l)_{ii}\neq 0$. With probability at least $1-\delta$,
\begin{equation}
\begin{aligned}
&||B^T(D_L+D''_L)\bm{W}'...(D_{l+1}+D''_{l+1})\cdot \bm{W}')-B^TD_L\bm{W}...\bm{W}D_{l+1}\cdot \bm{W}||\\
&\leq \mathcal{O}(\sum_{l_1=l+1}^L\underbrace{||B^T(D^0_L)\bm{W}^0...\bm{W}^0(D^{0/1}_{l_1})||}_{T_1}\cdot ||D''_{l_1}||\cdot \underbrace{||(D^{0/1}_{l_1})\bm{W}'D'_{l_1-1}...\bm{W}'(D'_{l+1})||}_{T_2})\\
&\overset{(a)}{\leq} \mathcal{O}(\sqrt{m}L^{5/3+8}\tau_0^{1/3}\log m\cdot m^{-1/6})\leq \mathcal{O}(\sqrt{m}L^{10}\omega^{1/3}\log m).
\end{aligned}
\end{equation}
In (a), $T_2\leq O(L^7)$ is from (c) in Lemma \ref{elem}.  From (d) in Lemma \ref{elem} and $||D''_l||_0\leq   \mathcal{O}(L^{10/3}\tau_0^{2/3}m^{2/3})$, $T_1\leq \sqrt{m}L^{5/3}\tau_0^{1/3}\log m\cdot m^{-1/6}$.
\hfill\ensuremath{\blacksquare

In this theorem,
\begin{equation}
|f(\bm{W}',x_i)-f(\bm{W},x_i)-\langle \nabla f(\bm{W},x_i), \bm{W}'-\bm{W}\rangle |\leq \mathcal{O}(\omega^{1/3}L^{10}\log m \sqrt{m})||\bm{W}'-\bm{W}||_2.
\end{equation}
And in \cite{cao}, there is a similar result that
\begin{equation}
|f(\bm{W}',x_i)-f(\bm{W},x_i)-\langle \nabla f(\bm{W},x_i), \bm{W}'-\bm{W}\rangle |\leq \mathcal{O}(\omega^{1/3}L^2\sqrt{\log m} \sqrt{m})||\bm{W}'-\bm{W}||_2.
\end{equation}
The differences on $\log m$ are from that Lemma 4.4 in \cite{allenzhu2019convergence} says if $||u||_0\leq s$, $|B^T(D_L+D''_L)\bm{W}'_L...(D_{l+1}+D''_{l+1})\cdot \bm{W}'_{l+1}u|\leq\mathcal{O}(\sqrt{s \log m}$
and Corollary B.18 in \cite{rate} says $|B^T(D_L+D''_L)\bm{W}'...(D_{l+1}+D''_{l+1})\cdot \bm{W}'u|\leq\mathcal{O}(\sqrt{s}\log m)$ for RNN case.

\label{lem1}
Denote $L_i(\bm{W})=\ell(y_i\cdot f(\bm{W},x_i))$. Suppose there exits $\bm{W}^* \in B(\bm{W}_0,R/\sqrt{m})$ with $R\leq poly(n,L)$, $L_i(\bm{W}^*)\leq \frac{1+R^2}{n}$. For any $ \delta$, there exists
\begin{equation}
m^*(n,\delta,R,L)=poly(n,R,L,\delta^{-1})
\end{equation}
such that if $m>m^*$, with probability at least $1-\delta$,  SGD with $\eta=1/m$ for some small enough $\nu$ will output:
\begin{equation}
\frac{1}{n}\sum_{i=1}^n L^{0-1}_{\emph{D}}(\bm{W}^{i})\leq \mathcal{O}(\frac{1}{ n})+ \mathcal{O}(\frac{R^2}{ n})+\mathcal{O}(\frac{\log(1/\delta)}{n}).
\end{equation}

Firstly, for all $i$, $\bm{W}\in B(\bm{W}_0, \omega), \omega\leq R/m^{1/2}$, from Lemma \ref{elem}, $||\nabla f(\bm{W},x_i)||_F\leq \mathcal{O}(L^{8}\sqrt{m})$.
\begin{equation}
||\bm{W}^{i+1}-\bm{W}^0||_F\leq \sum_{k=1}^i||\bm{W}^{k+1}-\bm{W}^k||_F\leq \mathcal{O}(n\eta L^{8}\sqrt{m})\leq \frac{L^{8} R}{\sqrt{m}}\leq \mathcal{O}(\tau_0/m^{1/2})
\end{equation}
with $\tau_0\leq poly(n,L)$.
Thus we can use Theorem \ref{lf}. We have,
\begin{equation}
\begin{aligned}
L_i(\bm{W}^{i})-L_i(\bm{W}^*)&\leq \langle \nabla_{\bm{W}}L_i(\bm{W}^{i}), \bm{W}^{i}-\bm{W}^*\rangle \\
&+ |\ell'(y_if(\bm{W},x_i))\cdot y_i|\cdot \mathcal{O}(\omega^{1/3}L^{10}\log m\sqrt{m})||\bm{W}^i-\bm{W}^*||_2\\
&=\frac{\langle \bm{W}^i-\bm{W}^{i+1}, \bm{W}^i-\bm{W}^*\rangle}{\eta}  + \mathcal{O}(\omega^{1/3}L^{10}\log m\sqrt{m})||\bm{W}^i-\bm{W}^*||_2
\end{aligned}
\end{equation}
Therefore,
\begin{equation}
\begin{aligned}
\sum_{i=1}^n L_i(\bm{W}^{i})&\leq \sum_{i=1}^n \{L_i(\bm{W}^*) +\frac{R^2}{2\eta m} + \mathcal{O}(\omega^{1/3}L^{10}\log m\sqrt{m})\sum_{i=1}^n||\bm{W}^i-\bm{W}^*||_2\},\\
&\leq \sum_{i=1}^n\{L_i(\bm{W}^*) +\frac{R^2}{2\eta m} + \mathcal{O}(L^{10}\log m\cdot n\cdot R^{4/3}\cdot m^{-1/6})\},\\
&\overset{(a)}{\leq} \sum_{i=1}^nL_i(\bm{W}^*) +  R^2.\\
\end{aligned}
\end{equation}
In (a), we use $m>m^*\sim poly(n,L)$.

Therefore,
\begin{equation}
\begin{aligned}
&\frac{1}{n}\sum_{i=1}^n L_i(\bm{W}^{i})\leq  \frac{1+R^2}{n} +  \frac{R^2}{n}.
\end{aligned}
\end{equation}
The cross-entropy function $\ell(x)$ satisfies that $L'_i(\bm{W}^{i}) \leq L_i(\bm{W}^{i})$ and $L^{0-1}_i(\bm{W}^{i})\leq L'_i(\bm{W}^{i}) $, where
\begin{equation}
L'_i(\bm{W}^{i})=-\ell'(y_if(\bm{W},x_i)).
\end{equation}
And $-\ell'(x)$ is bounded. Using the boundedness and a martingale Bernstein bound argument as Lemma 4.3 in \cite{ji2020polylogarithmic}, we have
\begin{equation}
\begin{aligned}
&\frac{1}{n}\sum_{i=1}^n L^{0-1}_D(\bm{W}^{i})\leq   \mathcal{O}(\frac{1}{ n})+\mathcal{O}(\frac{R^2}{n})+\mathcal{O}(\frac{\log(1/\delta)}{n}).
\end{aligned}
\end{equation}
\hfill\ensuremath{\blacksquare

\begin{equation}
\begin{aligned}
\sum_{i=1}^n L_i(\bm{W}^{i})&\leq \sum_{i=1}^n \{L_i(\bm{W}^*) +\frac{R^2}{2\eta m} + \mathcal{O}(\omega^{1/3}L^{10}\log m\sqrt{m})\sum_{i=1}^n||\bm{W}^i-\bm{W}^*||_2\},\\
&\leq \sum_{i=1}^n\{L_i(\bm{W}^*) +\frac{R^2}{2\eta m} + \mathcal{O}(L^{10}\log m\cdot n\cdot R^{4/3}\cdot m^{-1/6})\},\\
&\overset{(a)}{\leq} \sum_{i=1}^nL_i(\bm{W}^*) +  R^2.\\
\end{aligned}
\end{equation}

The result of generalization error $1/n$ is this better than that in \cite{cao} $1/\sqrt{n}$, which shows
\begin{equation}
\begin{aligned}
&\frac{1}{n}\sum_{i=1}^n L^{0-1}_D(\bm{W}^{i})\leq  \frac{4}{n}\sum_{i=1}^nL_i(\bm{W}^*) +  \mathcal{O}(\frac{R}{\sqrt{n}})+\mathcal{O}(\sqrt{\frac{\log(1/\delta)}{n}}).
\end{aligned}
\end{equation}
This is because Lemma 4.3 in \cite{ji2020polylogarithmic}  makes use of the boundedness of $L_i(\bm{W})$. Thus it is  applicable in this theorem. There is also a similar argument in Lemma 5.6 of  \cite{chen2020overparameterization}.

