Let $\bm{\epsilon}$ be the matrix in (\ref{condition1}),
$$\bm{G}=m^{-1/2}\cdot (vec[\nabla f(\bm{W}^0,x_1)], vec[\nabla f(\bm{W}^0,x_2)],... vec[\nabla f(\bm{W}^0,x_n)])\in \mathbb{R}^{m^2\times n}.$$
 \begin{equation}\label{svd}
\bm{G}+\bm{\epsilon}=\bm{P}\bm{\Lambda}\bm{Q}^T.
\end{equation}
 is the singular value decomposition. Note that $m^2\gg n$. We can set $ \bm{\epsilon}^T \bm{G} =0$ without changing $\bm{\epsilon^T\epsilon}$.

With probability at least $1-\delta$, for all $i\in [n]$, $ |f(\bm{W}^0,x_i)|\leq \mathcal{O}(L\log(n/\delta))$.
 We assume $w^*=\bm{P}\bm{\Lambda}^{-1}\bm{Q}^T(B\cdot \widetilde{y})$, with $0<|f(\bm{W}^0,x_i)|+\log\{1/[exp(n^{-1})-1]\}+0.01<B\leq \mathcal{O}(L\log(n/\delta))$ for all $i\in [n]$, then $||w^*||^2_2\leq B^2\widetilde{y}^T ( \bm{H}+\bm{\epsilon}^T\bm{\epsilon})^{-1} \widetilde{y}.$ and $\bm{G}^Tw^*=B\cdot \widetilde{y}-\bm{\epsilon}^Tw^*$. Meanwhile, reshape $w^*$ as $\bm{W}^*\in \mathbb{R}^{m\times m}$, then we have
 \begin{equation}
 \langle \nabla f(\bm{W}^0,x_i), \bm{W}^*-\bm{W}^0 \rangle =  B\cdot \widetilde{y}_i \pm||\bm{\epsilon}||_F \cdot \sqrt{\widetilde{y}^T (\bm{H}+\bm{\epsilon})^{-1}\widetilde{y}} = B\cdot \widetilde{y}_i \pm 0.01.
 \end{equation}
 Therefore $\bm{W}^* \in B(\bm{W}_0,\widetilde{O}(L\mathscr{C}^*/\sqrt{m}))$, and
 \begin{equation}
 \begin{aligned}
 \ell(y_i\cdot(f(\bm{W}^*,x_i)))&\leq\ell(y_i\cdot \{f(\bm{W}^0,x_i)+\langle \nabla f(\bm{W}^0,x_i), \bm{W}^*-\bm{W}^0 \rangle\}) \\
 &+|\ell'(y_if(\bm{W},x_i))\cdot y_i|\cdot \mathcal{O}(L^{10}\log m\cdot n\cdot R^{4/3}\cdot m^{-1/6})\\
 &\leq\ell(y_i\cdot \{f(\bm{W}^0,x_i)+\langle \nabla f(\bm{W}^0,x_i), \bm{W}^*-\bm{W}^0 \rangle\}) \\
 &+R^2/n\\
 &\leq \ell(\log(1/[exp(n^{-1})-1])) +R^2/n,\\
 & \leq n^{-1}+R^2/n.
 \end{aligned}
 \end{equation}
Thus $L_i(\bm{W}^*)\leq \frac{1+R^2}{n}$.
\hfill\ensuremath{\blacksquare

